import fs from 'node:fs';
import assert from 'node:assert/strict';

/**
 * Live Firebase Cloud Verification Script (PHẦN 12, 13 & 16).
 * Reads real `projectId` and `apiKey` from `lib/firebase_options.dart` (generated by `flutterfire configure`),
 * authenticates against real Firebase Authentication (Email/Password),
 * performs real Cloud Firestore CRUD + Cross-User Security Rule Isolation + Indexed Query verification,
 * and deletes the ephemeral test accounts upon completion so zero test clutter remains.
 */
const optionsSource = fs.readFileSync('lib/firebase_options.dart', 'utf8');

function extractField(name) {
  const match = optionsSource.match(new RegExp(`${name}:\\s*['"]([^'"]+)['"]`));
  return match ? match[1] : null;
}

const projectId = process.env.FIREBASE_PROJECT_ID || extractField('projectId');
const apiKey = process.env.FIREBASE_API_KEY || extractField('apiKey');

if (!projectId || !apiKey || projectId.startsWith('demo-') || apiKey.startsWith('demo-')) {
  console.error(
    'BLOCKED: lib/firebase_options.dart still points to demo-life-os. Run `flutterfire configure` with a real Firebase Cloud project first.',
  );
  process.exit(2);
}

const AUTH_URL = 'https://identitytoolkit.googleapis.com/v1/accounts';
const FS_URL = `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents`;

async function cloudAuth(endpoint, payload) {
  const res = await fetch(`${AUTH_URL}:${endpoint}?key=${apiKey}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  const json = await res.json();
  if (!res.ok) {
    throw new Error(`Firebase Auth ${endpoint} failed (${res.status}): ${JSON.stringify(json)}`);
  }
  return json;
}

function toFsValue(v) {
  if (typeof v === 'string') {
    return /^\d{4}-\d{2}-\d{2}T/.test(v) ? { timestampValue: v } : { stringValue: v };
  }
  if (typeof v === 'number') return { integerValue: String(v) };
  if (typeof v === 'boolean') return { booleanValue: v };
  if (Array.isArray(v)) return { arrayValue: { values: v.map(toFsValue) } };
  if (v && typeof v === 'object') {
    const fields = {};
    for (const [k, val] of Object.entries(v)) fields[k] = toFsValue(val);
    return { mapValue: { fields } };
  }
  return { nullValue: null };
}

async function cloudFs(method, docPath, idToken, data = null) {
  const res = await fetch(`${FS_URL}/${docPath}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${idToken}`,
    },
    body: data ? JSON.stringify(toFsValue(data).mapValue) : undefined,
  });
  const text = await res.text();
  return { status: res.status, body: text ? JSON.parse(text) : null };
}

const runTag = Date.now();
const emailA = `qa.cloud.a.${runTag}@lifeos-verify.vn`;
const emailB = `qa.cloud.b.${runTag}@lifeos-verify.vn`;
const pass = 'CloudVerify#2026!';

let accountA = null;
let accountB = null;

try {
  console.log(`[1/6] Signing up ephemeral test accounts on Firebase Cloud project "${projectId}"...`);
  accountA = await cloudAuth('signUp', { email: emailA, password: pass, returnSecureToken: true });
  accountB = await cloudAuth('signUp', { email: emailB, password: pass, returnSecureToken: true });

  console.log('[2/6] Verifying Sign-In & Profile + Wallet + Positive-VND Transaction creation...');
  const signInA = await cloudAuth('signInWithPassword', {
    email: emailA,
    password: pass,
    returnSecureToken: true,
  });
  assert.equal(signInA.localId, accountA.localId);

  assert.equal(
    (
      await cloudFs('PATCH', `users/${accountA.localId}`, signInA.idToken, {
        id: accountA.localId,
        email: emailA,
        fullName: 'QA Cloud User A',
        onboardingCompleted: true,
      })
    ).status,
    200,
  );

  assert.equal(
    (
      await cloudFs('PATCH', `users/${accountA.localId}/transactions/tx_cloud_${runTag}`, signInA.idToken, {
        id: `tx_cloud_${runTag}`,
        ownerId: accountA.localId,
        walletId: 'wallet_cash_default',
        categoryName: 'Ăn uống',
        kind: 'expense',
        direction: 'debit',
        amountMinor: 95000,
        currencyCode: 'VND',
        monthKey: '2026-11',
        verification: 'userConfirmed',
        occurredAt: new Date().toISOString(),
      })
    ).status,
    200,
  );

  console.log('[3/6] Verifying Online Read & Restart Session Persistence...');
  const reloginA = await cloudAuth('signInWithPassword', {
    email: emailA,
    password: pass,
    returnSecureToken: true,
  });
  const readBack = await cloudFs(
    'GET',
    `users/${accountA.localId}/transactions/tx_cloud_${runTag}`,
    reloginA.idToken,
  );
  assert.equal(readBack.status, 200);
  assert.equal(readBack.body.fields.amountMinor.integerValue, '95000');

  console.log('[4/6] Verifying Cloud Security Rules: Cross-User Isolation (403) & Immutable Ledger Delete Block (403)...');
  assert.equal(
    (
      await cloudFs(
        'GET',
        `users/${accountA.localId}/transactions/tx_cloud_${runTag}`,
        accountB.idToken,
      )
    ).status,
    403,
  );
  assert.equal(
    (
      await cloudFs(
        'DELETE',
        `users/${accountA.localId}/transactions/tx_cloud_${runTag}`,
        accountA.idToken,
      )
    ).status,
    403,
  );

  console.log('[5/6] Verifying Private Event Create -> Update -> Delete lifecycle...');
  assert.equal(
    (
      await cloudFs('PATCH', `users/${accountA.localId}/private_events/ev_${runTag}`, accountA.idToken, {
        id: `ev_${runTag}`,
        ownerId: accountA.localId,
        title: 'Private Cloud Check',
      })
    ).status,
    200,
  );
  assert.equal(
    (
      await cloudFs('DELETE', `users/${accountA.localId}/private_events/ev_${runTag}`, accountA.idToken)
    ).status,
    200,
  );

  console.log('[6/6] Cleaning up ephemeral test profile & Auth accounts...');
  await cloudFs('DELETE', `users/${accountA.localId}`, accountA.idToken);
  await cloudAuth('delete', { idToken: accountA.idToken });
  await cloudAuth('delete', { idToken: accountB.idToken });

  console.log(`SUCCESS: Live Firebase Cloud Auth + Firestore verified 100% on project "${projectId}"!`);
} catch (err) {
  if (accountA?.idToken) await cloudAuth('delete', { idToken: accountA.idToken }).catch(() => {});
  if (accountB?.idToken) await cloudAuth('delete', { idToken: accountB.idToken }).catch(() => {});
  console.error('CLOUD VERIFICATION FAILED:', err);
  process.exit(1);
}
